// Game simulation: player movement/collision, hitscan weapons, bot AI with
// waypoint navigation + line-of-sight, CS-style economy and round flow.

import { BOXES, MAT, PLAYER_SPAWN, BOT_SPAWNS, WAYPOINTS, WAYPOINT_EDGES } from './map.js';

export const WEAPONS = {
  knife:   { name: 'Tactical Knife', slot: 2, price: 0,    dmg: 38,  hsMult: 1.8, rpm: 120, mag: Infinity, reserve: Infinity, range: 2.4, spread: 0,     melee: true,  sfx: 'knife',        reloadTime: 0 },
  pistol:  { name: 'VP-9 Sidearm',   slot: 1, price: 0,    dmg: 28,  hsMult: 4,   rpm: 352, mag: 12, reserve: 36,  range: 999, spread: 0.011, auto: false, sfx: 'shot_pistol',  reloadTime: 1.6 },
  deagle:  { name: 'Hand Cannon',    slot: 1, price: 700,  dmg: 53,  hsMult: 4,   rpm: 267, mag: 7,  reserve: 28,  range: 999, spread: 0.02,  auto: false, sfx: 'shot_pistol',  reloadTime: 1.8 },
  smg:     { name: 'Vector SMG',     slot: 0, price: 1250, dmg: 21,  hsMult: 3,   rpm: 857, mag: 30, reserve: 90,  range: 999, spread: 0.022, auto: true,  sfx: 'shot_smg',     reloadTime: 1.9 },
  shotgun: { name: 'Breacher-12',    slot: 0, price: 1100, dmg: 9,   hsMult: 2,   rpm: 68,  mag: 7,  reserve: 28,  range: 999, spread: 0.05,  auto: false, pellets: 8, sfx: 'shot_shotgun', reloadTime: 2.6 },
  rifle:   { name: 'AV-47 Rifle',    slot: 0, price: 2700, dmg: 36,  hsMult: 4,   rpm: 600, mag: 30, reserve: 90,  range: 999, spread: 0.009, auto: true,  sfx: 'shot_rifle',   reloadTime: 2.2 },
  sniper:  { name: 'Longshot AWM',   slot: 0, price: 4750, dmg: 115, hsMult: 2,   rpm: 41,  mag: 5,  reserve: 20,  range: 999, spread: 0.001, auto: false, scoped: true, sfx: 'shot_sniper', reloadTime: 2.8 },
};

export const ARMOR_PRICE = 650;

const DIFFICULTY = {
  easy:   { reaction: 0.9,  spread: 0.09,  dmg: 9,  rpmScale: 0.5, viewDist: 32 },
  normal: { reaction: 0.55, spread: 0.05,  dmg: 14, rpmScale: 0.7, viewDist: 40 },
  hard:   { reaction: 0.35, spread: 0.028, dmg: 20, rpmScale: 0.85, viewDist: 48 },
  elite:  { reaction: 0.18, spread: 0.014, dmg: 26, rpmScale: 1.0, viewDist: 60 },
};

const PLAYER_RADIUS = 0.35;
const PLAYER_HEIGHT = 1.8;
const EYE_STAND = 1.62;
const EYE_CROUCH = 1.1;
const GRAVITY = 22;
const JUMP_VEL = 7.2;
const WALK_SPEED = 4.0;
const RUN_SPEED = 6.4;
const CROUCH_SPEED = 2.4;

// Solid boxes only (skip thin neon strips for movement so they don't snag)
const SOLIDS = BOXES.filter(b => b[6] !== MAT.NEON_CYAN && b[6] !== MAT.NEON_MAGENTA);

// ---------- collision ----------
function collideAxis(pos, half, axis, delta) {
  pos[axis] += delta;
  const min = [pos[0] - half[0], pos[1], pos[2] - half[2]];
  const max = [pos[0] + half[0], pos[1] + half[1] * 2, pos[2] + half[2]];
  for (const b of SOLIDS) {
    if (max[0] <= b[0] || min[0] >= b[3] || max[1] <= b[1] || min[1] >= b[4] || max[2] <= b[2] || min[2] >= b[5]) continue;
    if (delta > 0) pos[axis] = (axis === 1 ? b[1] - half[1] * 2 : b[axis] - half[axis === 0 ? 0 : 2]) - 1e-4;
    else pos[axis] = (axis === 1 ? b[4] : b[axis + 3] + half[axis === 0 ? 0 : 2]) + 1e-4;
    return true;
  }
  return false;
}

export function rayWorld(ro, rd, maxT) {
  // CPU mirror of the shader's box traversal — used for hitscan and LOS
  let best = maxT, hit = false;
  for (const b of SOLIDS) {
    let tmin = -Infinity, tmax = Infinity;
    for (let a = 0; a < 3; a++) {
      const inv = 1 / rd[a];
      let t0 = (b[a] - ro[a]) * inv;
      let t1 = (b[a + 3] - ro[a]) * inv;
      if (inv < 0) { const tmp = t0; t0 = t1; t1 = tmp; }
      tmin = Math.max(tmin, t0);
      tmax = Math.min(tmax, t1);
      if (tmin > tmax) break;
    }
    if (tmin <= tmax && tmax > 0.001) {
      const t = tmin > 0.001 ? tmin : tmax;
      if (t < best) { best = t; hit = true; }
    }
  }
  return hit ? best : -1;
}

function raySphere(ro, rd, c, r) {
  const oc = [ro[0] - c[0], ro[1] - c[1], ro[2] - c[2]];
  const b = oc[0] * rd[0] + oc[1] * rd[1] + oc[2] * rd[2];
  const cc = oc[0] ** 2 + oc[1] ** 2 + oc[2] ** 2 - r * r;
  const h = b * b - cc;
  if (h < 0) return -1;
  const t = -b - Math.sqrt(h);
  return t > 0 ? t : -1;
}

// ---------- waypoint graph ----------
const ADJ = WAYPOINTS.map(() => []);
for (const [a, b] of WAYPOINT_EDGES) { ADJ[a].push(b); ADJ[b].push(a); }

function nearestWaypoint(x, z) {
  let best = 0, bd = Infinity;
  for (let i = 0; i < WAYPOINTS.length; i++) {
    const d = (WAYPOINTS[i].x - x) ** 2 + (WAYPOINTS[i].z - z) ** 2;
    if (d < bd) { bd = d; best = i; }
  }
  return best;
}

function findPath(from, to) {
  if (from === to) return [to];
  const prev = new Array(WAYPOINTS.length).fill(-1);
  const q = [from];
  prev[from] = from;
  while (q.length) {
    const n = q.shift();
    if (n === to) break;
    for (const m of ADJ[n]) {
      if (prev[m] === -1) { prev[m] = n; q.push(m); }
    }
  }
  if (prev[to] === -1) return [to];
  const path = [to];
  let n = to;
  while (n !== from) { n = prev[n]; path.unshift(n); }
  return path;
}

// ---------- bots ----------
class Bot {
  constructor(i, spawn, diff) {
    this.id = i;
    this.name = `VEC-${i + 1}`;
    this.diff = diff;
    this.spawn = spawn;
    this.reset();
  }
  reset() {
    this.pos = [this.spawn.x, 0, this.spawn.z];
    this.hp = 100;
    this.alive = true;
    this.deathT = 0;
    this.state = 'patrol';
    this.path = [];
    this.pathI = 0;
    this.yaw = Math.random() * Math.PI * 2;
    this.seenT = 0;
    this.fireCd = Math.random() * 0.5;
    this.strafeDir = 1;
    this.strafeT = 0;
    this.lastKnown = null;
    this.repathT = 0;
  }
  headPos() { return [this.pos[0], this.pos[1] + 1.55, this.pos[2]]; }
  bodyPos() { return [this.pos[0], this.pos[1] + 0.9, this.pos[2]]; }
}

// ---------- game ----------
export class Game {
  constructor(settings, audio, events) {
    this.settings = settings;
    this.audio = audio;
    this.events = events; // { onKill, onRoundEnd, onDamage, onHitmarker, onShot, ... }
    this.state = 'menu';  // menu | buy | live | end | matchend
    this.score = { player: 0, bots: 0 };
    this.round = 0;
    this.money = 800;
    this.kills = 0;
    this.deaths = 0;
    this.time = 0;
    this.phaseT = 0;

    this.player = null;
    this.bots = [];
    this.input = { fwd: 0, strafe: 0, jump: false, crouch: false, walk: false, fire: false, scope: false };
    this.recoil = 0;
    this.spread = 0;
  }

  startMatch() {
    this.score = { player: 0, bots: 0 };
    this.round = 0;
    this.money = 800;
    this.kills = 0;
    this.deaths = 0;
    const diff = DIFFICULTY[this.settings.get('game.difficulty')];
    const n = Math.round(this.settings.get('game.botCount'));
    this.bots = [];
    for (let i = 0; i < n; i++) {
      this.bots.push(new Bot(i, BOT_SPAWNS[i % BOT_SPAWNS.length], diff));
    }
    this.player = {
      pos: [PLAYER_SPAWN.x, PLAYER_SPAWN.y, PLAYER_SPAWN.z],
      vel: [0, 0, 0],
      yaw: PLAYER_SPAWN.yaw,
      pitch: 0,
      hp: 100,
      armor: 0,
      onGround: true,
      crouching: false,
      weapons: { knife: { ammo: Infinity, reserve: Infinity }, pistol: { ammo: 12, reserve: 36 } },
      current: 'pistol',
      reloadT: 0,
      fireCd: 0,
      bobT: 0,
      scoped: false,
    };
    this.startRound();
  }

  startRound() {
    this.round++;
    this.state = 'buy';
    this.phaseT = 6;
    const p = this.player;
    p.pos = [PLAYER_SPAWN.x, PLAYER_SPAWN.y, PLAYER_SPAWN.z];
    p.vel = [0, 0, 0];
    p.hp = 100;
    p.reloadT = 0;
    p.scoped = false;
    // refill mags
    for (const [w, st] of Object.entries(p.weapons)) {
      const def = WEAPONS[w];
      if (def.mag !== Infinity) {
        const need = def.mag - st.ammo;
        const take = Math.min(need, st.reserve);
        st.ammo += take;
        st.reserve -= take;
        if (st.reserve < def.reserve) st.reserve = def.reserve; // fresh box each round
      }
    }
    for (const b of this.bots) b.reset();
    this.events.onPhase('buy');
    this.audio.play('round_start', { category: 'ui' });
  }

  goLive() {
    this.state = 'live';
    this.phaseT = this.settings.get('game.roundTime');
    this.events.onPhase('live');
  }

  endRound(playerWon, reason) {
    if (this.state === 'end' || this.state === 'matchend') return;
    this.state = 'end';
    this.phaseT = 3.5;
    if (playerWon) {
      this.score.player++;
      this.money = Math.min(16000, this.money + 3250);
      this.audio.play('round_win', { category: 'ui' });
    } else {
      this.score.bots++;
      this.money = Math.min(16000, this.money + 1400);
      this.audio.play('round_lose', { category: 'ui' });
    }
    this.events.onRoundEnd(playerWon, reason);
    if (this.score.player >= 8 || this.score.bots >= 8) {
      this.state = 'matchend';
      this.events.onMatchEnd(this.score.player >= 8);
    }
  }

  buy(item) {
    if (this.state !== 'buy' && !(this.state === 'live' && this.phaseT > this.settings.get('game.roundTime') - 10)) {
      this.audio.play('deny', { category: 'ui' });
      return false;
    }
    if (item === 'armor') {
      if (this.money < ARMOR_PRICE || this.player.armor >= 100) {
        this.audio.play('deny', { category: 'ui' });
        return false;
      }
      this.money -= ARMOR_PRICE;
      this.player.armor = 100;
      this.audio.play('buy', { category: 'ui' });
      return true;
    }
    const def = WEAPONS[item];
    if (!def || this.money < def.price || this.player.weapons[item]) {
      this.audio.play('deny', { category: 'ui' });
      return false;
    }
    this.money -= def.price;
    this.player.weapons[item] = { ammo: def.mag, reserve: def.reserve };
    this.player.current = item;
    this.audio.play('buy', { category: 'ui' });
    return true;
  }

  switchWeapon(slot) {
    const p = this.player;
    const owned = Object.keys(p.weapons).filter(w => WEAPONS[w].slot === slot);
    if (owned.length) {
      p.current = owned[owned.length - 1];
      p.reloadT = 0;
      p.scoped = false;
    }
  }

  // ---------- camera helpers ----------
  eyeHeight() {
    return this.player.crouching ? EYE_CROUCH : EYE_STAND;
  }
  camBasis() {
    const p = this.player;
    const cy = Math.cos(p.yaw), sy = Math.sin(p.yaw);
    const cp = Math.cos(p.pitch), sp = Math.sin(p.pitch);
    const fwd = [sy * cp, sp, -cy * cp];
    const right = [cy, 0, sy];
    const up = [
      right[1] * fwd[2] - right[2] * fwd[1],
      right[2] * fwd[0] - right[0] * fwd[2],
      right[0] * fwd[1] - right[1] * fwd[0],
    ];
    return { fwd, right, up };
  }
  eyePos() {
    const p = this.player;
    let bob = 0;
    if (this.settings.get('controls.viewBobbing')) {
      bob = Math.sin(p.bobT * 9) * 0.035 * Math.min(1, Math.hypot(p.vel[0], p.vel[2]) / RUN_SPEED);
    }
    return [p.pos[0], p.pos[1] + this.eyeHeight() + bob, p.pos[2]];
  }

  // ---------- firing ----------
  tryFire() {
    const p = this.player;
    if (p.fireCd > 0 || p.reloadT > 0) return;
    const def = WEAPONS[p.current];
    const st = p.weapons[p.current];
    if (!def.melee && st.ammo <= 0) {
      this.audio.play('dryfire', { category: 'sfx' });
      p.fireCd = 0.3;
      return;
    }
    p.fireCd = 60 / def.rpm;
    if (!def.melee) st.ammo--;

    const { fwd, right, up } = this.camBasis();
    const eye = this.eyePos();
    const pellets = def.pellets || 1;
    const moveSpread = Math.min(0.03, Math.hypot(p.vel[0], p.vel[2]) * 0.004);
    const totalSpread = (p.scoped ? def.spread * 0.2 : def.spread) + this.spread + moveSpread;
    let anyHit = false, anyHs = false;
    const hits = [];

    for (let pi = 0; pi < pellets; pi++) {
      const rx = (Math.random() - 0.5) * 2 * totalSpread;
      const ry = (Math.random() - 0.5) * 2 * totalSpread;
      const rd = norm3([
        fwd[0] + right[0] * rx + up[0] * ry,
        fwd[1] + right[1] * rx + up[1] * ry,
        fwd[2] + right[2] * rx + up[2] * ry,
      ]);
      const wallT = rayWorld(eye, rd, def.range);
      const maxT = wallT > 0 ? wallT : def.range;
      let bestBot = null, bestT = maxT, isHead = false;
      for (const b of this.bots) {
        if (!b.alive) continue;
        const th = raySphere(eye, rd, b.headPos(), 0.3);
        if (th > 0 && th < bestT) { bestT = th; bestBot = b; isHead = true; }
        const tb = raySphere(eye, rd, b.bodyPos(), 0.55);
        if (tb > 0 && tb < bestT) { bestT = tb; bestBot = b; isHead = false; }
      }
      if (bestBot) {
        const dmg = Math.round(def.dmg * (isHead ? def.hsMult : 1));
        this.damageBot(bestBot, dmg, isHead, p.current);
        anyHit = true;
        anyHs = anyHs || isHead;
        hits.push({ bot: bestBot, dmg, head: isHead, point: addScaled(eye, rd, bestT) });
      } else if (wallT > 0) {
        hits.push({ point: addScaled(eye, rd, wallT) });
      }
    }

    this.audio.play(def.sfx, { category: 'sfx' });
    if (anyHit && this.settings.get('audio.hitsound')) {
      this.audio.play(anyHs ? 'headshot' : 'hit', { category: 'ui', vol: 0.8 });
    }
    // recoil + bloom
    if (!def.melee) {
      p.pitch = Math.min(Math.PI / 2, p.pitch + (def.dmg / 1400) * (p.scoped ? 0.3 : 1));
      p.yaw += (Math.random() - 0.5) * 0.004;
      this.spread = Math.min(0.04, this.spread + def.spread * 0.8);
      this.recoil = 1;
    }
    this.events.onShot({ weapon: p.current, hits, headshot: anyHs, hit: anyHit });
  }

  damageBot(bot, dmg, isHead, weapon) {
    if (!bot.alive) return;
    bot.hp -= dmg;
    // getting shot alerts the bot
    bot.state = 'attack';
    bot.seenT = 0.5;
    this.events.onDamage(bot, dmg, isHead);
    if (bot.hp <= 0) {
      bot.alive = false;
      bot.deathT = 0.6;
      this.kills++;
      this.money = Math.min(16000, this.money + 300);
      const rel = this.relativeAudio(bot.pos);
      this.audio.play('bot_death', { category: 'sfx', pan: rel.pan, dist: rel.dist });
      this.events.onKill(bot, isHead, weapon);
      if (this.state === 'live' && this.bots.every(b => !b.alive)) {
        this.endRound(true, 'All hostiles eliminated');
      }
    }
  }

  reload() {
    const p = this.player;
    const def = WEAPONS[p.current];
    const st = p.weapons[p.current];
    if (def.melee || p.reloadT > 0 || st.ammo >= def.mag || st.reserve <= 0) return;
    p.reloadT = def.reloadTime;
    this.audio.play('reload', { category: 'sfx' });
  }

  relativeAudio(srcPos) {
    const eye = this.eyePos();
    const d = [srcPos[0] - eye[0], srcPos[1] - eye[1], srcPos[2] - eye[2]];
    const dist = Math.hypot(...d);
    const { right } = this.camBasis();
    const pan = dist > 0.01 ? (d[0] * right[0] + d[1] * right[1] + d[2] * right[2]) / dist : 0;
    return { pan, dist };
  }

  damagePlayer(dmg, srcPos) {
    const p = this.player;
    if (p.armor > 0) {
      const absorbed = Math.min(p.armor, dmg * 0.5);
      p.armor -= absorbed;
      dmg -= absorbed;
    }
    p.hp -= dmg;
    const rel = this.relativeAudio(srcPos);
    this.audio.play('hurt', { category: 'sfx', pan: rel.pan, vol: 0.9 });
    this.events.onPlayerDamage(dmg, srcPos);
    if (p.hp <= 0) {
      p.hp = 0;
      this.deaths++;
      this.endRound(false, 'You were eliminated');
    }
  }

  // ---------- per-frame ----------
  update(dt) {
    if (this.state === 'menu' || this.state === 'matchend') return;
    dt = Math.min(dt, 0.05);
    this.time += dt;

    if (this.state === 'buy') {
      this.phaseT -= dt;
      if (this.phaseT <= 0) this.goLive();
      this.updateViewmodelTimers(dt);
      return; // frozen during buy
    }
    if (this.state === 'end') {
      this.phaseT -= dt;
      this.updateBots(dt); // let corpses sink
      if (this.phaseT <= 0) this.startRound();
      return;
    }
    // live
    this.phaseT -= dt;
    if (this.phaseT <= 0) {
      this.endRound(false, 'Time expired');
      return;
    }
    this.updatePlayer(dt);
    this.updateBots(dt);
    this.updateViewmodelTimers(dt);
  }

  updateViewmodelTimers(dt) {
    const p = this.player;
    p.fireCd = Math.max(0, p.fireCd - dt);
    if (p.reloadT > 0) {
      p.reloadT -= dt;
      if (p.reloadT <= 0) {
        const def = WEAPONS[p.current];
        const st = p.weapons[p.current];
        const need = def.mag - st.ammo;
        const take = Math.min(need, st.reserve);
        st.ammo += take;
        st.reserve -= take;
      }
    }
    this.spread = Math.max(0, this.spread - dt * 0.06);
    this.recoil = Math.max(0, this.recoil - dt * 6);
  }

  updatePlayer(dt) {
    const p = this.player;
    const inp = this.input;
    p.crouching = inp.crouch;
    const speed = p.crouching ? CROUCH_SPEED : (inp.walk ? WALK_SPEED : RUN_SPEED);

    const cy = Math.cos(p.yaw), sy = Math.sin(p.yaw);
    let mx = (sy * inp.fwd + cy * inp.strafe);
    let mz = (-cy * inp.fwd + sy * inp.strafe);
    const ml = Math.hypot(mx, mz);
    if (ml > 1) { mx /= ml; mz /= ml; }

    // accelerate toward wish velocity (snappy, CS-like)
    const accel = p.onGround ? 14 : 2.5;
    p.vel[0] += (mx * speed - p.vel[0]) * Math.min(1, accel * dt);
    p.vel[2] += (mz * speed - p.vel[2]) * Math.min(1, accel * dt);

    if (inp.jump && p.onGround) {
      p.vel[1] = JUMP_VEL;
      p.onGround = false;
      this.audio.play('jump', { category: 'sfx', vol: 0.6 });
    }
    p.vel[1] -= GRAVITY * dt;

    const half = [PLAYER_RADIUS, (p.crouching ? 1.3 : PLAYER_HEIGHT) / 2, PLAYER_RADIUS];
    collideAxis(p.pos, half, 0, p.vel[0] * dt);
    collideAxis(p.pos, half, 2, p.vel[2] * dt);
    const wasAir = !p.onGround;
    const hitY = collideAxis(p.pos, half, 1, p.vel[1] * dt);
    if (hitY) {
      if (p.vel[1] < 0) {
        p.onGround = true;
        if (wasAir && p.vel[1] < -5) this.audio.play('land', { category: 'sfx', vol: 0.6 });
      }
      p.vel[1] = 0;
    } else if (p.pos[1] <= 0 && p.vel[1] <= 0) {
      p.pos[1] = 0;
      if (wasAir && p.vel[1] < -5) this.audio.play('land', { category: 'sfx', vol: 0.6 });
      p.vel[1] = 0;
      p.onGround = true;
    } else {
      p.onGround = false;
    }

    // footsteps
    const hSpeed = Math.hypot(p.vel[0], p.vel[2]);
    if (p.onGround && hSpeed > 1.5) {
      p.bobT += dt * (hSpeed / RUN_SPEED);
      if (!p._stepT) p._stepT = 0;
      p._stepT -= dt * (hSpeed / RUN_SPEED);
      if (p._stepT <= 0 && !inp.walk && !p.crouching) {
        p._stepT = 0.42;
        this.audio.play('footstep', { category: 'sfx', vol: 0.7 });
      }
    }

    // firing
    if (inp.fire) {
      const def = WEAPONS[p.current];
      if (def.auto || p._fireLatch !== true) {
        this.tryFire();
        p._fireLatch = true;
      }
    } else {
      p._fireLatch = false;
    }
    p.scoped = inp.scope && WEAPONS[p.current].scoped === true;
  }

  hasLOS(from, to) {
    const d = [to[0] - from[0], to[1] - from[1], to[2] - from[2]];
    const dist = Math.hypot(...d);
    if (dist < 0.01) return true;
    const rd = d.map(v => v / dist);
    const t = rayWorld(from, rd, dist - 0.05);
    return t < 0;
  }

  updateBots(dt) {
    const p = this.player;
    const eye = this.eyePos();
    for (const b of this.bots) {
      if (!b.alive) {
        if (b.deathT > 0) b.deathT -= dt;
        continue;
      }
      if (this.state !== 'live') continue;
      const head = b.headPos();
      const toP = [p.pos[0] - b.pos[0], 0, p.pos[2] - b.pos[2]];
      const distP = Math.hypot(toP[0], toP[2]);

      // vision: distance + facing cone + LOS
      let sees = false;
      if (distP < b.diff.viewDist) {
        const facing = [Math.sin(b.yaw), 0, -Math.cos(b.yaw)];
        const dot = (toP[0] * facing[0] + toP[2] * facing[2]) / (distP || 1);
        if (dot > 0.34 || distP < 4) {
          sees = this.hasLOS(head, eye);
        }
      }

      if (sees) {
        b.seenT += dt;
        b.lastKnown = [...p.pos];
        if (b.state !== 'attack' && b.seenT >= b.diff.reaction) b.state = 'attack';
      } else {
        b.seenT = Math.max(0, b.seenT - dt * 0.5);
        if (b.state === 'attack' && b.seenT <= 0) {
          b.state = 'seek';
          b.repathT = 0;
        }
      }

      if (b.state === 'attack' && sees) {
        // face player
        b.yaw = Math.atan2(toP[0], -toP[2]);
        // strafe
        b.strafeT -= dt;
        if (b.strafeT <= 0) { b.strafeT = 0.5 + Math.random(); b.strafeDir *= -1; }
        const sdx = Math.cos(b.yaw) * b.strafeDir, sdz = Math.sin(b.yaw) * b.strafeDir;
        this.moveBot(b, sdx * 2.2, sdz * 2.2, dt);
        // shoot
        b.fireCd -= dt;
        if (b.fireCd <= 0) {
          b.fireCd = (60 / 400) / b.diff.rpmScale;
          const spread = b.diff.spread * (1 + distP * 0.03);
          const miss = Math.random() * spread * distP;
          const rel = this.relativeAudio(head);
          this.audio.play('shot_rifle', { category: 'sfx', pan: rel.pan, dist: rel.dist, vol: 0.8 });
          this.events.onBotShot(b);
          if (miss < 0.55 && this.hasLOS(head, eye)) {
            this.damagePlayer(b.diff.dmg, head);
          }
        }
      } else {
        // navigate: patrol or seek last known position
        b.repathT -= dt;
        if (!b.path.length || b.pathI >= b.path.length || b.repathT <= 0) {
          const from = nearestWaypoint(b.pos[0], b.pos[2]);
          let targetWp;
          if (b.state === 'seek' && b.lastKnown) {
            targetWp = nearestWaypoint(b.lastKnown[0], b.lastKnown[2]);
            if (from === targetWp) { b.state = 'patrol'; b.lastKnown = null; }
          }
          if (b.state !== 'seek') {
            targetWp = Math.floor(Math.random() * WAYPOINTS.length);
          }
          b.path = findPath(from, targetWp);
          b.pathI = 0;
          b.repathT = 6 + Math.random() * 4;
        }
        const wp = WAYPOINTS[b.path[Math.min(b.pathI, b.path.length - 1)]];
        const dx = wp.x - b.pos[0], dz = wp.z - b.pos[2];
        const d = Math.hypot(dx, dz);
        if (d < 1.2) {
          b.pathI++;
        } else {
          const sp = b.state === 'seek' ? 4.6 : 3.2;
          b.yaw = Math.atan2(dx, -dz);
          this.moveBot(b, (dx / d) * sp, (dz / d) * sp, dt);
        }
      }
    }
  }

  moveBot(b, vx, vz, dt) {
    const half = [0.4, 0.9, 0.4];
    collideAxis(b.pos, half, 0, vx * dt);
    collideAxis(b.pos, half, 2, vz * dt);
    if (b.pos[1] > 0) b.pos[1] = Math.max(0, b.pos[1] - 8 * dt);
  }

  // spheres for the ray tracer
  renderSpheres() {
    const out = [];
    for (const b of this.bots) {
      if (!b.alive && b.deathT <= 0) continue;
      const sink = b.alive ? 0 : (1 - b.deathT / 0.6) * 1.6;
      out.push({ x: b.pos[0], y: b.pos[1] + 0.9 - sink, z: b.pos[2], r: 0.55, mat: MAT.BOT_BODY });
      out.push({ x: b.pos[0], y: b.pos[1] + 1.55 - sink, z: b.pos[2], r: 0.3, mat: MAT.BOT_HEAD });
    }
    return out;
  }
}

function norm3(v) {
  const l = Math.hypot(...v) || 1;
  return [v[0] / l, v[1] / l, v[2] / l];
}
function addScaled(a, d, t) {
  return [a[0] + d[0] * t, a[1] + d[1] * t, a[2] + d[2] * t];
}
